blocks.body:
{
    "level": "B1–B2",
    "intro": "У цій темі ти вивчиш <strong>каузативну конструкцію<\/strong> — спосіб сказати, що хтось інший виконує дію для тебе (зазвичай за гроші або на твоє прохання).",
    "rules": [
        {
            "label": "Have",
            "color": "emerald",
            "text": "<strong>have + object + V3<\/strong> (формальніше):",
            "example": "I had my car repaired. — Мені відремонтували машину."
        },
        {
            "label": "Get",
            "color": "blue",
            "text": "<strong>get + object + V3<\/strong> (розмовніше):",
            "example": "I got my hair cut. — Мене підстригли."
        },
        {
            "label": "Значення",
            "color": "amber",
            "text": "Хтось <strong>інший<\/strong> виконує дію для тебе:",
            "example": "I don't cut my hair myself — a hairdresser does it."
        }
    ]
}

{
    "title": "1. Каузатив vs Актив vs Пасив",
    "intro": "Порівняння трьох конструкцій:",
    "rows": [
        {
            "en": "Active: I repaired my car.",
            "ua": "Я відремонтував свою машину.",
            "note": "Я сам це зробив."
        },
        {
            "en": "Passive: My car was repaired.",
            "ua": "Мою машину відремонтували.",
            "note": "Хтось це зробив (невідомо хто)."
        },
        {
            "en": "Causative: I had my car repaired.",
            "ua": "Мені відремонтували машину.",
            "note": "Я замовив послугу (хтось зробив для мене)."
        }
    ],
    "warning": "📌 Каузатив підкреслює, що ми організували виконання дії, а не зробили її самі!"
}

{
    "title": "2. Have something done у різних часах",
    "intro": "Дієслово <strong>have<\/strong> змінюється за часами:",
    "items": [
        {
            "label": "Present Simple",
            "title": "have\/has + object + V3",
            "subtitle": "I have my hair cut every month."
        },
        {
            "label": "Past Simple",
            "title": "had + object + V3",
            "subtitle": "She had her car serviced yesterday."
        },
        {
            "label": "Future Simple",
            "title": "will have + object + V3",
            "subtitle": "I will have my suit cleaned tomorrow."
        },
        {
            "label": "Present Perfect",
            "title": "have\/has had + object + V3",
            "subtitle": "We have had our house painted."
        },
        {
            "label": "Present Continuous",
            "title": "am\/is\/are having + object + V3",
            "subtitle": "They are having their kitchen renovated."
        },
        {
            "label": "Modal verbs",
            "title": "modal + have + object + V3",
            "subtitle": "You should have your eyes tested."
        }
    ]
}

{
    "title": "3. Типові ситуації для каузативу",
    "sections": [
        {
            "label": "Послуги \/ сервіс",
            "color": "emerald",
            "description": "Коли ми <strong>замовляємо послугу<\/strong>:",
            "examples": [
                {
                    "en": "I had my hair cut yesterday.",
                    "ua": "Мене підстригли вчора."
                },
                {
                    "en": "She has her nails done every week.",
                    "ua": "Їй роблять манікюр щотижня."
                },
                {
                    "en": "We had the house painted last month.",
                    "ua": "Нам пофарбували будинок минулого місяця."
                }
            ]
        },
        {
            "label": "Ремонт \/ обслуговування",
            "color": "blue",
            "description": "Для <strong>ремонту та технічного обслуговування<\/strong>:",
            "examples": [
                {
                    "en": "I need to have my car serviced.",
                    "ua": "Мені потрібно здати машину на ТО."
                },
                {
                    "en": "They had their roof repaired.",
                    "ua": "Їм відремонтували дах."
                },
                {
                    "en": "You should have your brakes checked.",
                    "ua": "Тобі варто перевірити гальма."
                }
            ]
        },
        {
            "label": "Медичні послуги",
            "color": "amber",
            "description": "Для <strong>медичних<\/strong> процедур:",
            "examples": [
                {
                    "en": "I had my eyes tested last week.",
                    "ua": "Мені перевірили зір минулого тижня."
                },
                {
                    "en": "She needs to have her teeth cleaned.",
                    "ua": "Їй потрібно почистити зуби (у стоматолога)."
                },
                {
                    "en": "He had his blood pressure checked.",
                    "ua": "Йому виміряли тиск."
                }
            ]
        },
        {
            "label": "Доставка \/ встановлення",
            "color": "rose",
            "description": "Для <strong>доставки та встановлення<\/strong>:",
            "examples": [
                {
                    "en": "We had a new kitchen installed.",
                    "ua": "Нам встановили нову кухню."
                },
                {
                    "en": "They had the furniture delivered.",
                    "ua": "Їм доставили меблі."
                },
                {
                    "en": "I had the internet connected yesterday.",
                    "ua": "Мені вчора підключили інтернет."
                }
            ]
        }
    ]
}

{
    "title": "4. Have something done vs Get something done",
    "intro": "Обидві форми мають схоже значення, але є відмінності:",
    "rows": [
        {
            "en": "Have: I had my car repaired.",
            "ua": "Мені відремонтували машину.",
            "note": "Формальніше, нейтральне."
        },
        {
            "en": "Get: I got my car repaired.",
            "ua": "Мені відремонтували машину.",
            "note": "Розмовніше, підкреслює зусилля."
        },
        {
            "en": "Have: She had her dress made.",
            "ua": "Їй пошили сукню.",
            "note": "Стандартна послуга."
        },
        {
            "en": "Get: She finally got her dress made.",
            "ua": "Їй нарешті пошили сукню.",
            "note": "Підкреслює, що це було непросто."
        }
    ],
    "warning": "📌 Get часто підкреслює, що вам довелося докласти зусиль, щоб щось було зроблено!"
}

{
    "title": "5. Негативний каузатив (неприємні події)",
    "sections": [
        {
            "label": "Негативні події",
            "color": "rose",
            "description": "Каузатив також використовується для <strong>неприємних подій<\/strong>, що сталися з нами:",
            "examples": [
                {
                    "en": "I had my wallet stolen.",
                    "ua": "У мене вкрали гаманець."
                },
                {
                    "en": "She had her car broken into.",
                    "ua": "Їй зламали машину."
                },
                {
                    "en": "They had their house burgled.",
                    "ua": "Їх пограбували (вдерлися в будинок)."
                }
            ]
        },
        {
            "label": "Різниця в контексті",
            "color": "amber",
            "description": "Контекст визначає, чи це <strong>послуга<\/strong> чи <strong>неприємність<\/strong>:",
            "examples": [
                {
                    "en": "I had my hair cut. (послуга)",
                    "ua": "Мене підстригли (у перукарні)."
                },
                {
                    "en": "I had my bag stolen. (неприємність)",
                    "ua": "У мене вкрали сумку."
                },
                {
                    "en": "She had her phone repaired. (послуга)",
                    "ua": "Їй відремонтували телефон."
                }
            ]
        }
    ]
}

{
    "title": "6. Заперечення та питання",
    "intro": "Утворення заперечень та питань у каузативі:",
    "items": [
        {
            "label": "Заперечення (have)",
            "title": "don't\/doesn't\/didn't have + obj + V3",
            "subtitle": "I didn't have my car repaired."
        },
        {
            "label": "Заперечення (get)",
            "title": "don't\/doesn't\/didn't get + obj + V3",
            "subtitle": "She didn't get her hair done."
        },
        {
            "label": "Питання (have)",
            "title": "Do\/Does\/Did + subj + have + obj + V3?",
            "subtitle": "Did you have your car serviced?"
        },
        {
            "label": "Питання (get)",
            "title": "Do\/Does\/Did + subj + get + obj + V3?",
            "subtitle": "Did she get her dress made?"
        },
        {
            "label": "Wh-питання",
            "title": "Wh + do\/does\/did + subj + have\/get + obj + V3?",
            "subtitle": "Where did you have your hair cut?"
        },
        {
            "label": "Future",
            "title": "Will + subj + have\/get + obj + V3?",
            "subtitle": "Will you have the report finished?"
        }
    ]
}

{
    "title": "7. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Використання infinitive замість V3.",
            "wrong": "I had my car to repair.",
            "right": "✅ I had my car repaired."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Пропуск object між have\/get та V3.",
            "wrong": "I had repaired my car.",
            "right": "✅ I had my car repaired."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Плутання каузативу з активним станом.",
            "wrong": "I had cut my hair. (= я сам підстригся)",
            "right": "✅ I had my hair cut. (= мене підстригли)"
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Неправильний порядок слів.",
            "wrong": "I had repaired my car yesterday.",
            "right": "✅ I had my car repaired yesterday."
        }
    ]
}

{
    "title": "Passive Basics",
    "items": [
        {
            "label": "Formation Rules — Правила утворення пасиву",
            "current": false
        },
        {
            "label": "Passive with Modal Verbs — Пасив з модальними",
            "current": false
        },
        {
            "label": "Causative — have/get something done",
            "current": true
        },
        {
            "label": "Get-Passive — Розмовний пасив",
            "current": false
        },
        {
            "label": "Impersonal Passive — Безособовий пасив",
            "current": false
        },
        {
            "label": "Negatives & Questions in Passive — Питання й заперечення",
            "current": false
        },
        {
            "label": "Phrasal Verbs in Passive — Фразові дієслова",
            "current": false
        },
        {
            "label": "Restrictions — Обмеження пасиву",
            "current": false
        },
        {
            "label": "Two-object Verbs in Passive — give/send/offer",
            "current": false
        },
        {
            "label": "Common Mistakes in Passive — Типові помилки",
            "current": false
        },
        {
            "label": "Formality & Style in Passive — Формальність і стиль",
            "current": false
        }
    ]
}

{
    "level": "B1",
    "intro": "У цій темі ти вивчиш <strong>get-passive<\/strong> — розмовний варіант пасивного стану. Він підкреслює <strong>зміну стану, подію чи несподіванку<\/strong>, і часто має емоційний відтінок.",
    "rules": [
        {
            "label": "Be Passive",
            "color": "blue",
            "text": "<strong>be + V3<\/strong> — нейтральний, формальний:",
            "example": "He was fired last week."
        },
        {
            "label": "Get Passive",
            "color": "emerald",
            "text": "<strong>get + V3<\/strong> — розмовний, динамічний:",
            "example": "He got fired last week."
        },
        {
            "label": "Відтінок",
            "color": "rose",
            "text": "Get-passive = подія, зміна, несподіванка:",
            "example": "They got married in June."
        }
    ]
}

{
    "title": "1. Структура Get-passive",
    "intro": "Формула: <strong>get + Past Participle (V3)<\/strong>",
    "items": [
        {
            "label": "Формула",
            "title": "get + V3",
            "subtitle": "get замість be у пасиві"
        },
        {
            "label": "Часи",
            "title": "get змінюється за часами",
            "subtitle": "get\/gets\/got\/will get\/getting + V3"
        },
        {
            "label": "Стиль",
            "title": "Розмовний, неформальний",
            "subtitle": "Частіше в spoken English"
        },
        {
            "label": "Відтінок",
            "title": "Подія, зміна стану",
            "subtitle": "Щось трапилося (часто несподівано)"
        }
    ]
}

{
    "title": "2. Коли використовувати Get-passive?",
    "sections": [
        {
            "label": "Несподівані події",
            "color": "emerald",
            "description": "Коли щось <strong>трапилося несподівано<\/strong>, випадково.",
            "examples": [
                {
                    "en": "He got hit by a car.",
                    "ua": "Його збила машина."
                },
                {
                    "en": "She got caught in the rain.",
                    "ua": "Вона потрапила під дощ."
                },
                {
                    "en": "I got stuck in traffic.",
                    "ua": "Я застряг у заторі."
                }
            ]
        },
        {
            "label": "Негативні події",
            "color": "rose",
            "description": "Часто для <strong>негативних, неприємних<\/strong> ситуацій.",
            "examples": [
                {
                    "en": "He got fired from his job.",
                    "ua": "Його звільнили з роботи."
                },
                {
                    "en": "She got hurt in the accident.",
                    "ua": "Вона постраждала в аварії."
                },
                {
                    "en": "My phone got stolen.",
                    "ua": "Мій телефон вкрали."
                }
            ]
        },
        {
            "label": "Зміна стану",
            "color": "sky",
            "description": "Підкреслює <strong>перехід з одного стану в інший<\/strong>.",
            "examples": [
                {
                    "en": "They got married last year.",
                    "ua": "Вони одружилися минулого року."
                },
                {
                    "en": "He got promoted to manager.",
                    "ua": "Його підвищили до менеджера."
                },
                {
                    "en": "The window got broken.",
                    "ua": "Вікно розбилося."
                }
            ]
        },
        {
            "label": "Позитивні події",
            "color": "amber",
            "description": "Іноді для <strong>позитивних змін<\/strong> — але рідше.",
            "examples": [
                {
                    "en": "She got accepted to university.",
                    "ua": "Її прийняли до університету."
                },
                {
                    "en": "He got selected for the team.",
                    "ua": "Його відібрали в команду."
                },
                {
                    "en": "I got invited to the party.",
                    "ua": "Мене запросили на вечірку."
                }
            ]
        }
    ]
}

{
    "title": "3. Типові вирази з Get-passive",
    "sections": [
        {
            "label": "Особисте життя",
            "color": "emerald",
            "description": "Вирази про <strong>особисті події та стосунки<\/strong>.",
            "examples": [
                {
                    "en": "get married",
                    "ua": "одружитися"
                },
                {
                    "en": "get divorced",
                    "ua": "розлучитися"
                },
                {
                    "en": "get engaged",
                    "ua": "заручитися"
                }
            ]
        },
        {
            "label": "Робота",
            "color": "blue",
            "description": "Вирази про <strong>роботу та кар'єру<\/strong>.",
            "examples": [
                {
                    "en": "get hired",
                    "ua": "бути найнятим"
                },
                {
                    "en": "get fired",
                    "ua": "бути звільненим"
                },
                {
                    "en": "get promoted",
                    "ua": "отримати підвищення"
                },
                {
                    "en": "get paid",
                    "ua": "отримати зарплату"
                }
            ]
        },
        {
            "label": "Неприємності",
            "color": "rose",
            "description": "Вирази про <strong>проблеми та неприємності<\/strong>.",
            "examples": [
                {
                    "en": "get hurt",
                    "ua": "постраждати"
                },
                {
                    "en": "get injured",
                    "ua": "отримати травму"
                },
                {
                    "en": "get lost",
                    "ua": "заблукати"
                },
                {
                    "en": "get stuck",
                    "ua": "застрягти"
                }
            ]
        },
        {
            "label": "Інші ситуації",
            "color": "amber",
            "description": "Інші <strong>типові вирази<\/strong> з get-passive.",
            "examples": [
                {
                    "en": "get caught",
                    "ua": "бути спійманим"
                },
                {
                    "en": "get arrested",
                    "ua": "бути заарештованим"
                },
                {
                    "en": "get killed",
                    "ua": "бути вбитим"
                },
                {
                    "en": "get dressed",
                    "ua": "одягнутися"
                }
            ]
        }
    ]
}

{
    "title": "4. Get-passive у різних часах",
    "sections": [
        {
            "label": "Present Simple",
            "color": "emerald",
            "description": "<strong>get\/gets + V3<\/strong> — регулярні дії, звички.",
            "examples": [
                {
                    "en": "He often gets invited to parties.",
                    "ua": "Його часто запрошують на вечірки."
                },
                {
                    "en": "People get hurt in accidents every day.",
                    "ua": "Люди отримують травми в аваріях щодня."
                }
            ]
        },
        {
            "label": "Past Simple",
            "color": "blue",
            "description": "<strong>got + V3<\/strong> — конкретні події в минулому.",
            "examples": [
                {
                    "en": "She got promoted last month.",
                    "ua": "Її підвищили минулого місяця."
                },
                {
                    "en": "They got married in 2020.",
                    "ua": "Вони одружилися в 2020 році."
                }
            ]
        },
        {
            "label": "Future",
            "color": "sky",
            "description": "<strong>will get + V3<\/strong> \/ <strong>be going to get + V3<\/strong>.",
            "examples": [
                {
                    "en": "She will get paid tomorrow.",
                    "ua": "Їй заплатять завтра."
                },
                {
                    "en": "He is going to get fired if he is late again.",
                    "ua": "Його звільнять, якщо він знову запізниться."
                }
            ]
        },
        {
            "label": "Present Perfect",
            "color": "amber",
            "description": "<strong>have\/has got + V3<\/strong> — результат до теперішнього.",
            "examples": [
                {
                    "en": "She has got accepted to Harvard!",
                    "ua": "Її прийняли до Гарварду!"
                },
                {
                    "en": "I have got stuck in this traffic for an hour.",
                    "ua": "Я застряг у цьому заторі на годину."
                }
            ]
        }
    ]
}

{
    "title": "5. Be Passive vs Get Passive",
    "intro": "Порівняння стандартного пасиву з get-passive:",
    "rows": [
        {
            "en": "be + V3",
            "ua": "Нейтральний, формальний",
            "note": "The report was completed."
        },
        {
            "en": "get + V3",
            "ua": "Розмовний, неформальний",
            "note": "The report got completed."
        },
        {
            "en": "be + V3",
            "ua": "Стан або результат",
            "note": "The door is closed. (стан зараз)"
        },
        {
            "en": "get + V3",
            "ua": "Процес, зміна",
            "note": "The door got closed. (дія, подія)"
        },
        {
            "en": "be + V3",
            "ua": "Будь-які контексти",
            "note": "Підходить завжди."
        },
        {
            "en": "get + V3",
            "ua": "Часто несподівані події",
            "note": "Часто негативні, несподівані."
        }
    ],
    "warning": "📌 <strong>Get-passive<\/strong> частіше для несподіваних, негативних або динамічних подій!"
}

{
    "title": "6. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Використання get-passive у формальному контексті.",
            "wrong": "The contract got signed by the CEO. (formal)",
            "right": "✅ The contract was signed by the CEO."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Плутанина get + adjective vs get + V3.",
            "wrong": "I got interesting. (замість interested)",
            "right": "✅ I got interested in the topic."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Використання be замість get для зміни стану.",
            "wrong": "They were married last June. (стан)",
            "right": "✅ They got married last June. (подія)"
        }
    ]
